""""
LLM Provider 인터페이스 및 Mock 구현체
"""

import time


class LLMError(Exception):
    """기본 LLM 예외"""
    pass


class RateLimitError(LLMError):
    """429 Too Many Requests 예외"""
    pass


class TimeoutError(LLMError):
    """Timeout 예외"""
    pass


class ServiceUnavailableError(LLMError):
    """503 Service Unavailable 예외"""
    pass


class BaseLLMProvider:
    def __init__(self, name="base_provider"):
        self.name = name
        self.injected_error = None
        self.call_count = 0

    def set_error(self, error):
        self.injected_error = error

    def clear_error(self):
        self.injected_error = None

    def generate(self, prompt):
        self.call_count += 1
        if self.injected_error:
            raise self.injected_error
        return self._do_generate(prompt)

    def _do_generate(self, prompt):
        raise NotImplementedError()


class MockPrimaryLLM(BaseLLMProvider):
    def __init__(self):
        super().__init__(name="primary")

    def _do_generate(self, prompt):
        return {
            "summary": "정상 신호 분석 완료: 105.0 kWh",
            "severity": "INFO",
            "action_required": False
        }


class MockFallbackLLM(BaseLLMProvider):
    def __init__(self):
        super().__init__(name="fallback")

    def _do_generate(self, prompt):
        return {
            "summary": "대체 LLM 신호 분석 완료: 안정적 상태",
            "severity": "LOW",
            "action_required": False
        }
"
